'use client';

import { useIsNarrow } from '@/registry/ndeko/hooks/use-is-narrow';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { InlineSheet } from '@/registry/ndeko/ui/inline-sheet';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { Conversation, ConversationHeader } from './conversation';
import { CopilotPanel, type CopilotWork } from './copilot-panel';
import { SCRIPTED_TICKET } from './data';
import { RefundRequest } from './refund-request';
import { ReplyComposer } from './reply-composer';
import {
  INITIAL,
  LOOP_AFTER_MS,
  openOf,
  placementOf,
  reducer,
  REFUND_MS,
  RESTING,
  SCRIPT,
  SEND_MS,
  type Decision,
  type DraftStatus,
  type InboxState,
  type OpenTicket,
  type RefundStatus,
} from './session';
import { TicketList } from './ticket-list';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** The width of the `@4xl` container variant: under it the ticket list lives in a sheet. */
const LIST_SHEET_BELOW_REM = 56;

/** The width of the `@2xl` container variant: under it the copilot lives in a sheet. */
const COPILOT_SHEET_BELOW_REM = 42;

function ticketOfOpen(open: OpenTicket | null) {
  if (!open) {
    return null;
  }
  return open.ticket;
}

/** The copilot follows one ticket: its work, its draft and its refund show on that ticket only. */
function workOf(state: InboxState): CopilotWork | null {
  if (state.openId !== SCRIPTED_TICKET) {
    return null;
  }
  return {
    steps: state.steps,
    lookedUpFields: state.customerFields,
    articlesFound: state.articlesFound,
    refund: state.refund,
  };
}

function draftOf(state: InboxState): DraftStatus {
  if (state.openId !== SCRIPTED_TICKET) {
    return 'none';
  }
  return state.draft;
}

function refundOf(state: InboxState): RefundStatus {
  if (state.openId !== SCRIPTED_TICKET) {
    return 'none';
  }
  return state.refund;
}

/** Nothing calls a network. A real help desk plugs in here: the reply a person sends, and their answer to the refund. */
export type Application11Props = {
  onSend?: (text: string) => void;
  onApprove?: () => void;
  onDeny?: () => void;
};

export default function Application11({
  onSend,
  onApprove,
  onDeny,
}: Application11Props) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const isCompact = useIsNarrow(ref, LIST_SHEET_BELOW_REM);
  const isPhone = useIsNarrow(ref, COPILOT_SHEET_BELOW_REM);
  const open = openOf(state);
  const work = workOf(state);
  const draft = draftOf(state);
  const refund = refundOf(state);
  const isListShown = isCompact && state.isListOpen;
  const isCopilotShown = isPhone && state.isCopilotOpen;
  const isBehindSheet = isListShown || isCopilotShown;
  const hasRefund = refund !== 'none';
  const showsRefundAboveReply = isPhone && hasRefund;
  const canReplay = isFinished && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, state.spoken);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function focusReplyAtEnd() {
    requestAnimationFrame(() => {
      const field =
        ref.current?.querySelector<HTMLTextAreaElement>('[data-reply-field]');
      if (!field) {
        return;
      }
      const end = field.value.length;
      field.focus();
      field.setSelectionRange(end, end);
    });
  }

  function openTicket(id: string) {
    act({ type: 'opened', id });
    if (isListShown) {
      focusLater('[data-sheet-open="list"]');
    }
  }

  function send() {
    if (!open) {
      return;
    }
    if (open.live.send === 'sending') {
      return;
    }
    const { id } = open;
    const text = open.live.reply.trim();
    act({ type: 'sendPressed' });
    if (text === '') {
      return;
    }
    schedule(() => act({ type: 'delivered', id }), SEND_MS);
    onSend?.(text);
  }

  /** Insert leaves the reply ready to send as it is; Edit puts the caret at its end. */
  function insert() {
    act({ type: 'draftInserted' });
    focusLater('[data-reply-send]');
  }

  function edit() {
    act({ type: 'draftInserted' });
    focusReplyAtEnd();
  }

  function discard() {
    act({ type: 'draftDiscarded' });
    focusLater('[data-draft-restore]');
  }

  function restore() {
    act({ type: 'draftRestored' });
    focusLater('[data-reply-field]');
  }

  /** The two buttons leave with the request, so the focus goes to what replaces them: the line that says what was decided. */
  function decide(decision: Decision) {
    act({ type: 'refundDecided', decision });
    focusLater('[data-request]');
    if (decision === 'denied') {
      onDeny?.();
      return;
    }
    schedule(() => act({ type: 'refunded' }), REFUND_MS);
    onApprove?.();
  }

  function openList() {
    act({ type: 'listSheet', isOpen: true });
    focusLater('[data-sheet-close="list"]');
  }

  function closeList() {
    act({ type: 'listSheet', isOpen: false });
    focusLater('[data-sheet-open="list"]');
  }

  function openCopilot() {
    act({ type: 'copilotSheet', isOpen: true });
    focusLater('[data-sheet-close="copilot"]');
  }

  function closeCopilot() {
    act({ type: 'copilotSheet', isOpen: false });
    focusLater('[data-sheet-open="copilot"]');
  }

  const list = {
    live: state.live,
    openId: state.openId,
    placement: placementOf(state),
    pressed,
    onOpen: openTicket,
  };

  const copilot = {
    ticket: ticketOfOpen(open),
    work,
    pressed,
    onDecide: decide,
  };

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-sidebar text-foreground @container min-h-dvh w-full'
      >
        <div className='relative flex h-dvh min-h-[40rem] overflow-hidden'>
          <div
            inert={isBehindSheet}
            className='flex min-w-0 flex-1 gap-2 @2xl:p-2'
          >
            <aside
              aria-label='Tickets'
              className='hidden w-60 shrink-0 @4xl:flex'
            >
              {!isCompact && <TicketList {...list} />}
            </aside>
            <main className='bg-background @2xl:hairline-ring @2xl:ring-border flex min-w-0 flex-1 flex-col overflow-clip @2xl:rounded-xl @2xl:shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
              <ConversationHeader
                open={open}
                canReplay={canReplay}
                onReplay={restart}
                onOpenList={openList}
                onOpenCopilot={openCopilot}
              />
              {!open && <Conversation ticket={null} />}
              {open && (
                <Conversation
                  ticket={open.ticket}
                  live={open.live}
                  refund={refund}
                />
              )}
              {open && (
                <div className='mx-auto flex min-h-0 w-full max-w-2xl shrink flex-col gap-2 overflow-y-auto px-3 pt-1 pb-3 @2xl:px-4 @2xl:pb-4'>
                  {showsRefundAboveReply && (
                    <RefundRequest
                      status={refund}
                      pressed={pressed}
                      isCompact
                      onDecide={decide}
                      className='shrink-0'
                    />
                  )}
                  <ReplyComposer
                    live={open.live}
                    draft={draft}
                    showsSendHint={state.showsSendHint}
                    emptySends={state.emptySends}
                    isActive={isInView}
                    isInsertPressed={pressed === 'insert'}
                    isSendPressed={pressed === 'send'}
                    onType={(text) => act({ type: 'replyTyped', text })}
                    onSend={send}
                    onInsert={insert}
                    onEdit={edit}
                    onDiscard={discard}
                    onRestore={restore}
                  />
                </div>
              )}
            </main>
            <aside
              aria-label='Copilot'
              className='hidden w-72 shrink-0 py-1 @2xl:flex @4xl:w-80'
            >
              {!isPhone && (
                <CopilotPanel {...copilot} showsRefund className='w-full' />
              )}
            </aside>
          </div>

          <InlineSheet
            name='list'
            label='Tickets'
            closeLabel='Close the ticket list'
            side='start'
            isOpen={isListShown}
            className='@4xl:hidden'
            panelClassName='bg-sidebar gap-1 p-3'
            onClose={closeList}
          >
            {isCompact && <TicketList {...list} />}
          </InlineSheet>
          <InlineSheet
            name='copilot'
            label='Copilot'
            closeLabel='Close the copilot'
            side='bottom'
            isOpen={isCopilotShown}
            className='@2xl:hidden'
            panelClassName='bg-sidebar h-[80%] gap-1 p-3'
            onClose={closeCopilot}
          >
            {isPhone && (
              <CopilotPanel
                {...copilot}
                showsRefund={false}
                className='min-h-0 flex-1'
              />
            )}
          </InlineSheet>
          <LiveRegion message={message} />
        </div>
      </div>
    </ClockGate>
  );
}

'use client';

import { LayoutGroup, motion, type Transition } from 'motion/react';
import { useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { springOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';

import {
  BRAND,
  TICKETS,
  type Priority,
  type Ticket,
  type TicketStatus,
} from './data';
import type { TicketLive } from './session';

type GroupId = 'open' | 'solved';

const GROUPS: { id: GroupId; label: string; emptyLine: string }[] = [
  { id: 'open', label: 'Open', emptyLine: 'Every ticket is solved' },
  { id: 'solved', label: 'Solved', emptyLine: 'Solved tickets land here' },
];

const STATUS_WORD: Record<TicketStatus, string> = {
  open: 'Open',
  pending: 'Pending',
  solved: 'Solved',
};

const STATUS_VARIANT: Record<TicketStatus, 'info' | 'warning' | 'success'> = {
  open: 'info',
  pending: 'warning',
  solved: 'success',
};

const PRIORITY_WORD: Record<Priority, string> = {
  high: 'High priority',
  normal: 'Normal priority',
  low: 'Low priority',
};

const PRIORITY_BARS: Record<Priority, number> = { high: 3, normal: 2, low: 1 };

const BAR_HEIGHTS = ['h-1', 'h-2', 'h-3'];

function groupOf(status: TicketStatus): GroupId {
  if (status === 'solved') {
    return 'solved';
  }
  return 'open';
}

function barToneOf(isFilled: boolean) {
  if (isFilled) {
    return 'bg-foreground/70';
  }
  return 'bg-foreground/15';
}

export function PriorityBars({ priority }: { priority: Priority }) {
  const filled = PRIORITY_BARS[priority];

  return (
    <span className='inline-flex shrink-0 items-end gap-0.5'>
      {BAR_HEIGHTS.map((height, index) => {
        const isFilled = index < filled;
        return (
          <span
            key={height}
            aria-hidden='true'
            className={cn('w-[3px] rounded-full', height, barToneOf(isFilled))}
          />
        );
      })}
      <span className='sr-only'>{PRIORITY_WORD[priority]}</span>
    </span>
  );
}

export function StatusBadge({ status }: { status: TicketStatus }) {
  return (
    <Swap swapKey={status}>
      <Badge variant={STATUS_VARIANT[status]}>{STATUS_WORD[status]}</Badge>
    </Swap>
  );
}

function currentOf(isOpen: boolean): 'true' | undefined {
  if (isOpen) {
    return 'true';
  }
  return undefined;
}

function rowToneOf(isOpen: boolean) {
  if (isOpen) {
    return 'bg-foreground/[0.07]';
  }
  return 'hover:bg-foreground/[0.04]';
}

function nameWeightOf(isUnread: boolean) {
  if (isUnread) {
    return 'font-semibold';
  }
  return 'font-medium';
}

type TicketRowProps = {
  ticket: Ticket;
  live: TicketLive;
  isOpen: boolean;
  isPressed: boolean;
  placement: string;
  travel: Transition;
  onOpen: (id: string) => void;
};

/** A ticket that is solved keeps its layout id, so its row travels from Open to Solved. */
function TicketRow({
  ticket,
  live,
  isOpen,
  isPressed,
  placement,
  travel,
  onOpen,
}: TicketRowProps) {
  function open() {
    onOpen(ticket.id);
  }

  return (
    <motion.li
      layout='position'
      layoutId={ticket.id}
      layoutDependency={placement}
      transition={{ layout: travel }}
    >
      <button
        type='button'
        aria-current={currentOf(isOpen)}
        onClick={open}
        className={cn(
          'focus-visible:ring-ring/25 flex w-full cursor-pointer flex-col gap-1 rounded-lg px-2.5 py-2 text-start transition-[background-color,scale] duration-150 outline-none focus-visible:ring-[3px]',
          rowToneOf(isOpen),
          pressedQuietOf(isPressed)
        )}
      >
        <span className='flex items-center gap-2'>
          {live.isUnread && (
            <span className='bg-primary size-1.5 shrink-0 rounded-full'>
              <span className='sr-only'>Unread</span>
            </span>
          )}
          <span
            className={cn(
              'min-w-0 flex-1 truncate text-[13px]',
              nameWeightOf(live.isUnread)
            )}
          >
            {ticket.customer.name}
          </span>
          <span className='text-muted-foreground shrink-0 text-xs tabular-nums'>
            {ticket.receivedAgo}
          </span>
        </span>
        <span className='text-muted-foreground truncate text-xs'>
          {ticket.subject}
        </span>
        <span className='flex items-center gap-2 pt-0.5'>
          <StatusBadge status={live.status} />
          <PriorityBars priority={ticket.priority} />
        </span>
      </button>
    </motion.li>
  );
}

type TicketListProps = {
  live: Record<string, TicketLive>;
  openId: string | null;
  placement: string;
  pressed: string | null;
  onOpen: (id: string) => void;
};

export function TicketList({
  live,
  openId,
  placement,
  pressed,
  onOpen,
}: TicketListProps) {
  const groupId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const travel = springOf(shouldReduceMotion);

  return (
    <div className='flex min-h-0 w-full flex-col gap-3'>
      <div className='flex h-9 shrink-0 items-center gap-2 px-1.5'>
        <CompanyMark seed={BRAND.name} className='size-6 rounded-md' />
        <span className='text-[13px] font-semibold'>{BRAND.name}</span>
        <span className='text-muted-foreground text-xs'>{BRAND.desk}</span>
      </div>
      <LayoutGroup id={groupId}>
        <nav
          aria-label='Tickets'
          className='-mx-1 flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-1'
        >
          {GROUPS.map((group) => {
            const tickets = TICKETS.filter((ticket) => {
              const ticketGroup = groupOf(live[ticket.id].status);
              return ticketGroup === group.id;
            });
            const isEmpty = tickets.length === 0;
            return (
              <section key={group.id} className='flex flex-col gap-1'>
                <motion.h2
                  layout='position'
                  layoutDependency={placement}
                  transition={{ layout: travel }}
                  className='text-muted-foreground flex h-6 items-center gap-1.5 px-2.5 text-xs font-medium'
                >
                  {group.label}
                  <LayoutGroup inherit={false}>
                    <MotionNumber value={tickets.length} />
                  </LayoutGroup>
                </motion.h2>
                <ul className='flex flex-col gap-px'>
                  {tickets.map((ticket) => {
                    const pressKey = `ticket-${ticket.id}`;
                    return (
                      <TicketRow
                        key={ticket.id}
                        ticket={ticket}
                        live={live[ticket.id]}
                        isOpen={ticket.id === openId}
                        isPressed={pressed === pressKey}
                        placement={placement}
                        travel={travel}
                        onOpen={onOpen}
                      />
                    );
                  })}
                </ul>
                {isEmpty && (
                  <p className='text-muted-foreground px-2.5 text-xs'>
                    {group.emptyLine}
                  </p>
                )}
              </section>
            );
          })}
        </nav>
      </LayoutGroup>
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { useFollowBottom } from '@/registry/ndeko/hooks/use-follow-bottom';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  CheckIcon,
  CircleXIcon,
  ImageIcon,
  InboxIcon,
  MenuIcon,
} from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Button } from '@/registry/ndeko/ui/button';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { ME, REFUND, type Ticket } from './data';
import type { OpenTicket, RefundStatus, TicketLive } from './session';
import { PriorityBars, StatusBadge } from './ticket-list';

function PersonAvatar({ name }: { name: string }) {
  return <Avatar className='size-7 shrink-0' seed={name} />;
}

function CustomerBubble({ ticket }: { ticket: Ticket }) {
  return (
    <div className='flex items-end gap-2 pb-4'>
      <PersonAvatar name={ticket.customer.name} />
      <div className='flex max-w-[85%] flex-col gap-1.5'>
        <p className='bg-foreground/[0.06] rounded-2xl rounded-es-md px-3.5 py-2 text-sm leading-relaxed'>
          {ticket.message}
        </p>
        {ticket.attachment && (
          <span className='bg-foreground/[0.04] text-muted-foreground flex h-7 w-fit items-center gap-1.5 rounded-lg px-2 text-xs'>
            <ImageIcon className='size-3.5' />
            {ticket.attachment}
          </span>
        )}
      </div>
    </div>
  );
}

function ReplyBubble({ text }: { text: string }) {
  return (
    <div className='flex items-end justify-end gap-2 pb-4'>
      <p className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] max-w-[85%] rounded-2xl rounded-ee-md px-3.5 py-2 text-sm leading-relaxed whitespace-pre-line shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        {text}
      </p>
      <PersonAvatar name={ME.name} />
    </div>
  );
}

type EventLineProps = {
  icon: React.ReactNode;
  children: React.ReactNode;
};

function EventLine({ icon, children }: EventLineProps) {
  return (
    <p className='text-muted-foreground flex items-center justify-center gap-1.5 pb-4 text-center text-xs'>
      {icon}
      {children}
    </p>
  );
}

function RefundLine({ status }: { status: RefundStatus }) {
  if (status === 'issued') {
    return (
      <EventLine
        icon={<CheckIcon className='text-success-foreground size-3.5' />}
      >
        Refund of {REFUND.amount} issued to {REFUND.card}
      </EventLine>
    );
  }
  return (
    <EventLine icon={<CircleXIcon className='size-3.5' />}>
      No refund was issued
    </EventLine>
  );
}

type ConversationHeaderProps = {
  open: OpenTicket | null;
  canReplay: boolean;
  onReplay: () => void;
  onOpenList: () => void;
  onOpenCopilot: () => void;
};

export function ConversationHeader({
  open,
  canReplay,
  onReplay,
  onOpenList,
  onOpenCopilot,
}: ConversationHeaderProps) {
  return (
    <header className='flex h-14 shrink-0 items-center gap-2.5 px-3 @2xl:px-4'>
      <Button
        type='button'
        variant='ghost'
        size='icon-sm'
        data-sheet-open='list'
        aria-label='Open the ticket list'
        aria-haspopup='dialog'
        onClick={onOpenList}
        className='text-muted-foreground @4xl:hidden'
      >
        <MenuIcon />
      </Button>
      {!open && (
        <h1 className='min-w-0 flex-1 truncate text-sm font-medium'>Inbox</h1>
      )}
      {open && (
        <div className='flex min-w-0 flex-1 flex-col leading-tight'>
          <h1 className='truncate text-sm font-medium'>
            {open.ticket.subject}
          </h1>
          <p className='text-muted-foreground truncate text-xs'>
            {open.ticket.customer.name}
          </p>
        </div>
      )}
      {open && (
        <span className='hidden @sm:inline-flex'>
          <PriorityBars priority={open.ticket.priority} />
        </span>
      )}
      {open && <StatusBadge status={open.live.status} />}
      <ReplayButton isShown={canReplay} onReplay={onReplay} label='Replay' />
      <Button
        type='button'
        variant='outline'
        size='sm'
        data-sheet-open='copilot'
        aria-haspopup='dialog'
        onClick={onOpenCopilot}
        className='@2xl:hidden'
      >
        Copilot
      </Button>
    </header>
  );
}

function EmptyConversation() {
  return (
    <div className='m-auto flex max-w-xs flex-col items-center gap-3 px-4 text-center'>
      <span
        aria-hidden='true'
        className='keycap-3d text-muted-foreground inline-flex size-10 items-center justify-center rounded-lg'
      >
        <InboxIcon className='size-5' />
      </span>
      <p className='text-sm font-medium'>Pick a ticket</p>
      <p className='text-muted-foreground text-[13px] leading-relaxed'>
        The copilot reads it, looks up the customer and drafts a reply you can
        insert, edit or discard.
      </p>
    </div>
  );
}

type MessagesProps = {
  ticket: Ticket;
  live: TicketLive;
  refund: RefundStatus;
};

/** The refund belongs to one ticket: on any other, `refund` is `none` and no line about it shows. */
function Messages({ ticket, live, refund }: MessagesProps) {
  const { scrollerRef, contentRef, updatePinned } = useFollowBottom();
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const isRefundSettled = refund === 'issued' || refund === 'denied';
  const isSolved = live.status === 'solved';

  return (
    <div
      ref={scrollerRef}
      onScroll={updatePinned}
      className='min-h-24 flex-1 overflow-y-auto'
    >
      <div
        ref={contentRef}
        className='mx-auto flex w-full max-w-2xl flex-col px-4 pt-4'
      >
        <CustomerBubble ticket={ticket} />
        <AnimatePresence initial={false}>
          {isRefundSettled && (
            <motion.div
              key='refund'
              className='overflow-hidden'
              {...rowPresence}
            >
              <RefundLine status={refund} />
            </motion.div>
          )}
          {live.sentReplies.map((reply, index) => (
            <motion.div
              key={`reply-${index}`}
              className='-mx-1 overflow-hidden px-1'
              {...rowPresence}
            >
              <ReplyBubble text={reply} />
            </motion.div>
          ))}
          {isSolved && (
            <motion.div
              key='solved'
              className='overflow-hidden'
              {...rowPresence}
            >
              <EventLine
                icon={
                  <CheckIcon className='text-success-foreground size-3.5' />
                }
              >
                Marked as solved
              </EventLine>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

type ConversationProps = MessagesProps | { ticket: null };

/** Keyed by ticket, so opening another one swaps the messages without replaying their entrance. */
export function Conversation(props: ConversationProps) {
  if (props.ticket === null) {
    return (
      <div className='flex min-h-0 flex-1'>
        <EmptyConversation />
      </div>
    );
  }
  return <Messages key={props.ticket.id} {...props} />;
}

'use client';

import { motion } from 'motion/react';
import { useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import {
  CircleCheckIcon,
  SendIcon,
  UndoIcon,
} from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Kbd, KbdGroup } from '@/registry/ndeko/ui/kbd';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';

import { EMPTY_SEND_HINT } from './data';
import { DraftCard } from './draft-card';
import type { DraftStatus, SendStatus, TicketLive } from './session';

const SEND_STATE: Record<SendStatus, MorphState> = {
  idle: 'idle',
  sending: 'busy',
  sent: 'done',
};

const SEND_LABELS: Record<MorphState, string> = {
  idle: 'Send',
  busy: 'Sending',
  done: 'Sent',
};

/** The gap under the draft sits inside what resizes, so an empty draft area takes no room at all. */
const TRACE =
  'text-muted-foreground mb-2 flex min-h-7 items-center gap-1.5 px-1 text-xs transition-opacity duration-300 starting:opacity-0';

const NUDGE = { x: [0, -4, 4, 0] };

const STILL = { x: 0 };

/** A refused entry nudges its reason once. Reduced motion keeps it still. */
function nudgeOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return STILL;
  }
  return NUDGE;
}

function describedByOf(showsHint: boolean, hintId: string) {
  if (showsHint) {
    return hintId;
  }
  return undefined;
}

function placeholderOf(draft: DraftStatus) {
  if (draft === 'streaming') {
    return 'The copilot is drafting a reply';
  }
  return 'Write a reply';
}

type DraftAreaProps = {
  draft: DraftStatus;
  isActive: boolean;
  isInsertPressed: boolean;
  onInsert: () => void;
  onEdit: () => void;
  onDiscard: () => void;
  onRestore: () => void;
};

function DraftArea({
  draft,
  isActive,
  isInsertPressed,
  onInsert,
  onEdit,
  onDiscard,
  onRestore,
}: DraftAreaProps) {
  const isStreaming = draft === 'streaming';
  const showsCard = isStreaming || draft === 'ready';

  if (showsCard) {
    return (
      <div className='pb-2'>
        <DraftCard
          isStreaming={isStreaming}
          isActive={isActive}
          isInsertPressed={isInsertPressed}
          onInsert={onInsert}
          onEdit={onEdit}
          onDiscard={onDiscard}
        />
      </div>
    );
  }
  if (draft === 'inserted') {
    return (
      <p className={TRACE}>
        <CircleCheckIcon className='text-success-foreground size-3.5 shrink-0' />
        Draft inserted. Read it through before you send
      </p>
    );
  }
  if (draft === 'discarded') {
    return (
      <p className={TRACE}>
        Draft discarded
        <Button
          type='button'
          variant='ghost'
          size='sm'
          data-draft-restore
          onClick={onRestore}
          className='text-muted-foreground h-6 px-1.5'
        >
          <UndoIcon className='size-3.5' />
          Restore
        </Button>
      </p>
    );
  }
  return null;
}

type ReplyComposerProps = DraftAreaProps & {
  live: TicketLive;
  showsSendHint: boolean;
  emptySends: number;
  isSendPressed: boolean;
  onType: (text: string) => void;
  onSend: () => void;
};

/** The draft arrives in the box a person answers from, above the field it will be inserted into. */
export function ReplyComposer({
  live,
  showsSendHint,
  emptySends,
  isSendPressed,
  onType,
  onSend,
  ...draftArea
}: ReplyComposerProps) {
  const hintId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();

  function sendFromKeys(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    const hasModifier = event.metaKey || event.ctrlKey;
    const isSendKey = event.key === 'Enter' && hasModifier;
    if (!isSendKey) {
      return;
    }
    event.preventDefault();
    onSend();
  }

  return (
    <div className='bg-card hairline-ring ring-foreground/12 has-[textarea:focus-visible]:ring-ring/25 dark:bg-foreground/[0.04] dark:ring-foreground/15 flex flex-col rounded-2xl p-2 shadow-[0_1px_2px_rgb(0_0_0/0.05)] transition-[box-shadow] duration-150 has-[textarea:focus-visible]:ring-[3px]'>
      <AnimatedSize>
        <DraftArea {...draftArea} />
      </AnimatedSize>
      <textarea
        data-reply-field
        value={live.reply}
        rows={2}
        aria-label='Reply to the customer'
        aria-invalid={showsSendHint}
        aria-describedby={describedByOf(showsSendHint, hintId)}
        placeholder={placeholderOf(draftArea.draft)}
        onChange={(event) => onType(event.target.value)}
        onKeyDown={sendFromKeys}
        className='placeholder:text-muted-foreground/75 field-sizing-content max-h-[9lh] min-h-[2lh] resize-none bg-transparent px-1.5 py-1 text-base leading-normal outline-none md:text-[13px]'
      />
      <div className='flex min-h-7 items-center gap-2 pt-2'>
        <div className='min-w-0 flex-1 px-1.5'>
          {showsSendHint && (
            <motion.p
              key={emptySends}
              id={hintId}
              animate={nudgeOf(shouldReduceMotion)}
              transition={{ duration: 0.28 }}
              className='text-destructive-ink text-xs'
            >
              {EMPTY_SEND_HINT}
            </motion.p>
          )}
          {!showsSendHint && (
            <p className='text-muted-foreground hidden items-center gap-1.5 text-xs @md:flex'>
              <KbdGroup aria-hidden='true'>
                <Kbd>Ctrl</Kbd>
                <Kbd>Enter</Kbd>
              </KbdGroup>
              <span className='sr-only'>Control or Command with Enter</span>
              sends
            </p>
          )}
        </div>
        <MorphButton
          type='button'
          size='sm'
          data-reply-send
          state={SEND_STATE[live.send]}
          labels={SEND_LABELS}
          idleIcon={<SendIcon />}
          onClick={onSend}
          className={pressedSolidOf(isSendPressed)}
        />
      </div>
    </div>
  );
}

'use client';

import { Fragment } from 'react';

import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { BookOpenIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { countOf, leadingSpaceOf } from '@/registry/ndeko/lib/words';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import {
  inkClassOf,
  shownCountOf,
  StreamCaret,
  useRevealedCount,
} from '@/registry/ndeko/ui/streamed-text';

import { ARTICLES, DRAFT_TOKENS, WRITER, type Article } from './data';
import { DRAFT_WORD_MS } from './session';

const MARK =
  'keycap-3d text-muted-foreground inline-flex h-4 min-w-4 items-center justify-center rounded-[4px] px-1 text-[10px] leading-none font-medium tabular-nums';

/** Each source lands a little after the one before it. */
const LANDING_DELAY = ['delay-0', 'delay-100', 'delay-200'];

function statusOf(isStreaming: boolean) {
  if (isStreaming) {
    return 'Writing';
  }
  return countOf(ARTICLES.length, 'source');
}

/** A source waits out of sight while the draft streams, then settles from a slightly larger size. */
function landingOf(hasLanded: boolean) {
  if (hasLanded) {
    return 'scale-100 opacity-100';
  }
  return 'invisible scale-[1.04] opacity-0';
}

type SourceChipProps = {
  article: Article;
  order: number;
  hasLanded: boolean;
};

function SourceChip({ article, order, hasLanded }: SourceChipProps) {
  return (
    <li
      className={cn(
        'bg-card dark:bg-foreground/[0.06] flex h-7 max-w-full items-center gap-1.5 rounded-full ps-1.5 pe-2.5 text-xs transition-[opacity,scale] duration-300 ease-(--ease-out-strong)',
        LANDING_DELAY[order],
        landingOf(hasLanded)
      )}
    >
      <span className={cn(MARK, 'rounded-full')}>{article.number}</span>
      <BookOpenIcon className='text-muted-foreground size-3.5 shrink-0' />
      <span className='min-w-0 truncate'>{article.title}</span>
    </li>
  );
}

type DraftCardProps = {
  isStreaming: boolean;
  isActive: boolean;
  isInsertPressed: boolean;
  onInsert: () => void;
  onEdit: () => void;
  onDiscard: () => void;
};

/** Only the draft re-renders while it streams. */
export function DraftCard({
  isStreaming,
  isActive,
  isInsertPressed,
  onInsert,
  onEdit,
  onDiscard,
}: DraftCardProps) {
  const total = DRAFT_TOKENS.length;
  const isRunning = isStreaming && isActive;
  const count = useRevealedCount(total, isRunning, DRAFT_WORD_MS);
  const shown = shownCountOf(isStreaming, count, total);
  const lastShown = shown - 1;
  const status = statusOf(isStreaming);

  return (
    <section
      aria-label='Draft from the copilot'
      className='bg-foreground/[0.04] flex flex-col gap-2.5 rounded-lg p-3'
    >
      <header className='flex items-center gap-2'>
        <MeshTile seed={WRITER.name} color={seriesColorOf(WRITER.series)} />
        <h2 className='min-w-0 flex-1 truncate text-[13px] font-medium'>
          Draft from the copilot
        </h2>
        <Swap swapKey={status} className='text-muted-foreground text-xs'>
          {status}
        </Swap>
      </header>
      <p className='text-[13px] leading-relaxed'>
        {DRAFT_TOKENS.map((token, index) => {
          const isShown = index < shown;
          const ink = inkClassOf(isStreaming, isShown);
          if (token.kind === 'cite') {
            return (
              <span
                key={index}
                className={cn(MARK, 'ms-1 align-[0.12em]', ink)}
              >
                <span className='sr-only'>Source </span>
                {token.article}
              </span>
            );
          }
          const hasCaret = isStreaming && index === lastShown;
          return (
            <Fragment key={index}>
              {leadingSpaceOf(index)}
              <span className={ink}>
                {token.text}
                {hasCaret && <StreamCaret />}
              </span>
            </Fragment>
          );
        })}
      </p>
      <ul aria-label='Sources of the draft' className='flex flex-wrap gap-1.5'>
        {ARTICLES.map((article, index) => (
          <SourceChip
            key={article.number}
            article={article}
            order={index}
            hasLanded={!isStreaming}
          />
        ))}
      </ul>
      <div className='flex flex-wrap items-center gap-2'>
        <Button
          type='button'
          size='sm'
          aria-label='Insert the draft'
          disabled={isStreaming}
          onClick={onInsert}
          className={pressedSolidOf(isInsertPressed)}
        >
          Insert
        </Button>
        <Button
          type='button'
          size='sm'
          variant='outline'
          aria-label='Edit the draft'
          disabled={isStreaming}
          onClick={onEdit}
        >
          Edit
        </Button>
        <Button
          type='button'
          size='sm'
          variant='ghost'
          aria-label='Discard the draft'
          disabled={isStreaming}
          onClick={onDiscard}
          className='text-muted-foreground'
        >
          Discard
        </Button>
      </div>
    </section>
  );
}

'use client';

import { WordRoll } from '@/components/core/word-roll';
import { useFollowBottom } from '@/registry/ndeko/hooks/use-follow-bottom';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

import { CopilotSteps } from './copilot-steps';
import { CustomerCard } from './customer-card';
import {
  CUSTOMER_FIELDS,
  MODEL,
  WRITER,
  type StepId,
  type Ticket,
} from './data';
import { RefundRequest } from './refund-request';
import type { Decision, RefundStatus, StepRun } from './session';

const WORKING_WORD: Record<StepId, string> = {
  read: 'Reading the ticket',
  lookup: 'Looking up the customer',
  search: 'Searching the help center',
  draft: 'Drafting a reply',
};

const RESTING_WORDS = [
  'Nothing to suggest',
  'Waiting on you',
  'Starting',
  'Done',
];

const WORKING_WORDS = Object.values(WORKING_WORD);

const STATUS_WORDS = [...WORKING_WORDS, ...RESTING_WORDS];

export type CopilotWork = {
  steps: StepRun[];
  lookedUpFields: number;
  articlesFound: number;
  refund: RefundStatus;
};

function statusOf(work: CopilotWork | null) {
  if (!work) {
    return 'Nothing to suggest';
  }
  if (work.refund === 'asking') {
    return 'Waiting on you';
  }
  const running = work.steps.find((run) => run.status === 'running');
  if (running) {
    return WORKING_WORD[running.id];
  }
  if (work.steps.length === 0) {
    return 'Starting';
  }
  return 'Done';
}

function lookedUpOf(work: CopilotWork | null) {
  if (!work) {
    return CUSTOMER_FIELDS.length;
  }
  return work.lookedUpFields;
}

/** The request only shows where the panel is asked to show it, and only once the copilot has asked. */
function requestOf(work: CopilotWork | null, showsRefund: boolean) {
  if (!work || !showsRefund) {
    return null;
  }
  if (work.refund === 'none') {
    return null;
  }
  return work.refund;
}

/**
 * The copilot follows one ticket: `work` is null on any other, where the panel shows the customer and
 * nothing to suggest. On a phone the refund request sits above the reply box, so `showsRefund` is false.
 */
type CopilotPanelProps = {
  ticket: Ticket | null;
  work: CopilotWork | null;
  showsRefund: boolean;
  pressed: string | null;
  onDecide: (decision: Decision) => void;
  className?: string;
};

export function CopilotPanel({
  ticket,
  work,
  showsRefund,
  pressed,
  onDecide,
  className,
}: CopilotPanelProps) {
  const { scrollerRef, contentRef, updatePinned } = useFollowBottom();
  const status = statusOf(work);
  const request = requestOf(work, showsRefund);
  const hasTicket = ticket !== null;
  const showsNothingToSuggest = hasTicket && !work;

  return (
    <div className={cn('flex min-h-0 flex-col gap-3', className)}>
      <header className='flex shrink-0 items-start gap-2.5 px-1'>
        <MeshTile
          seed={WRITER.name}
          color={seriesColorOf(WRITER.series)}
          size='lg'
        />
        <div className='flex min-w-0 flex-1 flex-col leading-tight'>
          <div className='flex items-center gap-2'>
            <h2 className='min-w-0 flex-1 truncate text-sm font-medium'>
              Copilot
            </h2>
            <span className='text-muted-foreground flex shrink-0 items-center gap-1.5 text-xs'>
              <BrandTile brand={MODEL.brand} />
              {MODEL.name}
            </span>
          </div>
          {ticket && (
            <span className='text-muted-foreground text-xs'>
              <WordRoll text={status} labels={STATUS_WORDS} />
            </span>
          )}
        </div>
      </header>

      {/* The scroller exists before a ticket is open, so it is there to follow once cards arrive. */}
      <div
        ref={scrollerRef}
        onScroll={updatePinned}
        className='-mx-1 min-h-0 flex-1 overflow-y-auto px-1 pb-1'
      >
        <div ref={contentRef} className='flex flex-col gap-3'>
          {!ticket && (
            <p className='text-muted-foreground px-1 text-[13px] leading-relaxed'>
              Open a ticket and the copilot gets to work: it reads the message,
              looks up the customer and searches the help center.
            </p>
          )}
          {ticket && (
            <CustomerCard
              customer={ticket.customer}
              lookedUpFields={lookedUpOf(work)}
            />
          )}
          {work && (
            <div className='px-2'>
              <CopilotSteps
                steps={work.steps}
                articlesFound={work.articlesFound}
              />
            </div>
          )}
          {showsNothingToSuggest && (
            <p className='text-muted-foreground px-1 text-xs leading-5'>
              Nothing to suggest here. This demonstration follows one ticket,
              the torn bag.
            </p>
          )}
          {request && (
            <RefundRequest
              status={request}
              pressed={pressed}
              onDecide={onDecide}
            />
          )}
          {ticket && (
            <Badge variant='secondary' className='mx-1'>
              Illustrative figures
            </Badge>
          )}
        </div>
      </div>
    </div>
  );
}

import { Avatar } from '@/registry/ndeko/ui/avatar';

import { CUSTOMER_FIELDS, type Customer } from './data';

type CustomerCardProps = {
  customer: Customer;
  lookedUpFields: number;
};

/** A field the copilot has not looked up yet shows a bar where its value will be. */
export function CustomerCard({ customer, lookedUpFields }: CustomerCardProps) {
  return (
    <section
      aria-label='Customer'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] flex flex-col gap-3 rounded-xl p-3 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <div className='flex items-center gap-2.5'>
        <Avatar seed={customer.name} />
        <div className='flex min-w-0 flex-col leading-tight'>
